package domain

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"time"
)

const hubAOCurrentnessVersion = "hub.ao-activation-currentness/1"
const hubAOCurrentnessSigningDomain = "hub.ao-activation-currentness-attestation/1\n"
const hubAOPermitEnvelopeDomain = "hub.ao-activation-permit-envelope/1\n"
const hubAOCurrentnessMaxAge = 5 * time.Second

// HubAOCurrentnessChallenge must be generated by AO for one activation attempt.
// Its permit digest covers the complete signed permit, including proof.bytes.
type HubAOCurrentnessChallenge struct {
	ContractVersion        string `json:"contractVersion"`
	PermitContractVersion  string `json:"permitContractVersion"`
	ActivationAttemptID    string `json:"activationAttemptId"`
	Nonce                  string `json:"nonce"`
	PermitDigest           string `json:"permitDigest"`
	GrantID                string `json:"grantId"`
	GrantDigest            string `json:"grantDigest"`
	RedemptionID           string `json:"redemptionId"`
	GraphID                string `json:"graphId"`
	ProjectID              string `json:"projectId"`
	GraphContractDigest    string `json:"graphContractDigest"`
	PrepareID              string `json:"prepareId"`
	GraphBytesSHA256       string `json:"graphBytesSha256"`
	ReceiptIdentitySHA256  string `json:"receiptIdentitySha256"`
	HubAOPlanBindingDigest string `json:"hubAOPlanBindingDigest"`
	HostID                 string `json:"hostId"`
	StoreID                string `json:"storeId"`
	HostGeneration         int64  `json:"hostGeneration"`
	AuthorityEpoch         int64  `json:"authorityEpoch"`
	PermitIssuedAt         string `json:"permitIssuedAt"`
	PermitUseBy            string `json:"permitUseBy"`
}

type HubAOCurrentnessAttestation struct {
	HubAOCurrentnessChallenge
	CheckID   string     `json:"checkId"`
	Allow     bool       `json:"allow"`
	CheckedAt string     `json:"checkedAt"`
	UseBy     string     `json:"useBy"`
	Proof     HubAOProof `json:"proof"`
}

func canonicalHubAOCurrentness(value any) (string, error) {
	raw, err := json.Marshal(value)
	if err != nil {
		return "", err
	}
	var decoded any
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return "", err
	}
	var canonical bytes.Buffer
	if err := writeHubCanonicalJSON(&canonical, decoded); err != nil {
		return "", err
	}
	return canonical.String(), nil
}

func HubAOPermitEnvelopeDigest(permit HubAOPermit) (string, error) {
	raw, err := json.Marshal(permit)
	if err != nil {
		return "", err
	}
	if _, err := ParseHubAOPermit(raw); err != nil {
		return "", err
	}
	canonical, err := canonicalHubAOCurrentness(permit)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256([]byte(hubAOPermitEnvelopeDomain + canonical))
	return hex.EncodeToString(sum[:]), nil
}

func validHubAOCurrentnessToken(value string, maxLength int) bool {
	alphaNumeric := func(c byte) bool {
		return c >= '0' && c <= '9' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z'
	}
	if len(value) == 0 || len(value) > maxLength || !alphaNumeric(value[0]) {
		return false
	}
	for i := 1; i < len(value); i++ {
		c := value[i]
		if !alphaNumeric(c) && c != '.' && c != '_' && c != ':' && c != '-' {
			return false
		}
	}
	return true
}

func validHubAORawBase64URL(value string, size int) bool {
	if len(value) != base64.RawURLEncoding.EncodedLen(size) {
		return false
	}
	decoded, err := base64.RawURLEncoding.DecodeString(value)
	return err == nil && len(decoded) == size && base64.RawURLEncoding.EncodeToString(decoded) == value
}

func (challenge HubAOCurrentnessChallenge) validate() error {
	if challenge.ContractVersion != hubAOCurrentnessVersion || challenge.PermitContractVersion != hubAODispatchVersion ||
		!validHubAOCurrentnessToken(challenge.ActivationAttemptID, 128) || !validHubAORawBase64URL(challenge.Nonce, 32) ||
		!validLowerHex(challenge.PermitDigest, 64) || !validHubAOID(challenge.GrantID) || !validHubAOID(challenge.RedemptionID) ||
		!validHubAOID(challenge.GraphID) || !validHubAOID(challenge.ProjectID) || !validHubAOPrepareID(challenge.PrepareID) ||
		!validHubAOID(challenge.HostID) || !validHubAOID(challenge.StoreID) ||
		challenge.HostGeneration <= 0 || challenge.HostGeneration > 9007199254740991 ||
		challenge.AuthorityEpoch < 0 || challenge.AuthorityEpoch > 9007199254740991 {
		return errors.New("Hub AO currentness: invalid challenge")
	}
	for _, digest := range []string{challenge.GrantDigest, challenge.GraphContractDigest, challenge.GraphBytesSHA256,
		challenge.ReceiptIdentitySHA256, challenge.HubAOPlanBindingDigest} {
		if !validLowerHex(digest, 64) {
			return errors.New("Hub AO currentness: invalid digest")
		}
	}
	issued, err := hubAOInstant(challenge.PermitIssuedAt)
	if err != nil {
		return err
	}
	useBy, err := hubAOInstant(challenge.PermitUseBy)
	if err != nil || !useBy.After(issued) {
		return errors.New("Hub AO currentness: invalid permit interval")
	}
	return nil
}

func buildHubAOCurrentnessChallenge(permit HubAOPermit, attemptID, nonce string) (HubAOCurrentnessChallenge, error) {
	digest, err := HubAOPermitEnvelopeDigest(permit)
	if err != nil {
		return HubAOCurrentnessChallenge{}, err
	}
	challenge := HubAOCurrentnessChallenge{
		ContractVersion: hubAOCurrentnessVersion, PermitContractVersion: permit.ContractVersion,
		ActivationAttemptID: attemptID, Nonce: nonce, PermitDigest: digest,
		GrantID: permit.GrantID, GrantDigest: permit.GrantDigest, RedemptionID: permit.RedemptionID,
		GraphID: permit.GraphID, ProjectID: permit.ProjectID, GraphContractDigest: permit.GraphContractDigest,
		PrepareID: permit.PrepareID, GraphBytesSHA256: permit.GraphBytesSHA256,
		ReceiptIdentitySHA256: permit.ReceiptIdentitySHA256, HubAOPlanBindingDigest: permit.HubAOPlanBindingDigest,
		HostID: permit.HostID, StoreID: permit.StoreID, HostGeneration: permit.HostGeneration,
		AuthorityEpoch: permit.AuthorityEpoch, PermitIssuedAt: permit.IssuedAt, PermitUseBy: permit.UseBy,
	}
	return challenge, challenge.validate()
}

// NewHubAOCurrentnessChallenge verifies the permit against local state, then
// generates an unpredictable AO attempt ID and nonce. The later caller must
// preserve this exact challenge and use it once; no network call occurs here.
func NewHubAOCurrentnessChallenge(rawPermit []byte, trusted HubAOPermitVerificationContext) (HubAOCurrentnessChallenge, error) {
	permit, err := VerifyHubAOEd25519Permit(rawPermit, trusted)
	if err != nil {
		return HubAOCurrentnessChallenge{}, err
	}
	var random [48]byte
	if _, err := rand.Read(random[:]); err != nil {
		return HubAOCurrentnessChallenge{}, err
	}
	return buildHubAOCurrentnessChallenge(permit, "ao-"+hex.EncodeToString(random[:16]), base64.RawURLEncoding.EncodeToString(random[16:]))
}

func ParseHubAOCurrentnessAttestation(raw []byte) (HubAOCurrentnessAttestation, error) {
	var attestation HubAOCurrentnessAttestation
	if err := strictHubAOJSON(raw, &attestation); err != nil {
		return attestation, err
	}
	if err := requireHubAOFields(raw, "contractVersion", "permitContractVersion", "activationAttemptId", "nonce", "permitDigest",
		"grantId", "grantDigest", "redemptionId", "graphId", "projectId", "graphContractDigest", "prepareId", "graphBytesSha256",
		"receiptIdentitySha256", "hubAOPlanBindingDigest", "hostId", "storeId", "hostGeneration", "authorityEpoch",
		"permitIssuedAt", "permitUseBy", "checkId", "allow", "checkedAt", "useBy", "proof"); err != nil {
		return attestation, err
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(raw, &fields); err != nil {
		return attestation, err
	}
	if err := requireHubAOFields(fields["proof"], "scheme", "keyId", "bytes"); err != nil {
		return attestation, err
	}
	if err := attestation.HubAOCurrentnessChallenge.validate(); err != nil {
		return attestation, err
	}
	if !validHubAOCurrentnessToken(attestation.CheckID, 128) || attestation.Proof.Scheme != "signature" ||
		!validHubAOID(attestation.Proof.KeyID) || !validHubAORawBase64URL(attestation.Proof.Bytes, ed25519.SignatureSize) {
		return attestation, errors.New("Hub AO currentness: invalid attestation proof")
	}
	checked, err := hubAOInstant(attestation.CheckedAt)
	if err != nil {
		return attestation, err
	}
	useBy, err := hubAOInstant(attestation.UseBy)
	permitIssued, _ := hubAOInstant(attestation.PermitIssuedAt)
	permitUseBy, _ := hubAOInstant(attestation.PermitUseBy)
	if err != nil || checked.Before(permitIssued) || !checked.Before(permitUseBy) ||
		!useBy.After(checked) || useBy.After(permitUseBy) || useBy.Sub(checked) > hubAOCurrentnessMaxAge {
		return attestation, errors.New("Hub AO currentness: invalid attestation interval")
	}
	return attestation, nil
}

func HubAOCurrentnessSigningBytes(attestation HubAOCurrentnessAttestation) (string, error) {
	raw, err := json.Marshal(attestation)
	if err != nil {
		return "", err
	}
	if _, err := ParseHubAOCurrentnessAttestation(raw); err != nil {
		return "", err
	}
	attestation.Proof.Bytes = ""
	valueRaw, err := json.Marshal(attestation)
	if err != nil {
		return "", err
	}
	var value map[string]any
	if err := json.Unmarshal(valueRaw, &value); err != nil {
		return "", err
	}
	value["proof"] = map[string]any{"scheme": attestation.Proof.Scheme, "keyId": attestation.Proof.KeyID}
	canonical, err := canonicalHubAOCurrentness(value)
	if err != nil {
		return "", err
	}
	return hubAOCurrentnessSigningDomain + canonical, nil
}

// VerifyHubAOCurrentnessAttestation checks Hub #414's exact signed response
// against a locally verified permit, prepared receipt, host/store generation,
// enrolled key and preserved AO attempt. It does not contact Hub, consume the
// check ID, or commit activation. A fresh check narrows but cannot eliminate
// revocation between Hub's response and AO's later local commit.
func VerifyHubAOCurrentnessAttestation(raw []byte, expected HubAOCurrentnessChallenge, rawPermit []byte,
	trusted HubAOPermitVerificationContext, now time.Time, consumedCheckIDs []string) (HubAOCurrentnessAttestation, error) {
	refuse := errors.New("Hub AO currentness: verification refused")
	if now.IsZero() || expected.validate() != nil {
		return HubAOCurrentnessAttestation{}, refuse
	}
	trusted.Now = now
	permit, err := VerifyHubAOEd25519Permit(rawPermit, trusted)
	if err != nil {
		return HubAOCurrentnessAttestation{}, refuse
	}
	derived, err := buildHubAOCurrentnessChallenge(permit, expected.ActivationAttemptID, expected.Nonce)
	if err != nil || derived != expected {
		return HubAOCurrentnessAttestation{}, refuse
	}
	attestation, err := ParseHubAOCurrentnessAttestation(raw)
	if err != nil || attestation.HubAOCurrentnessChallenge != expected || !attestation.Allow ||
		attestation.Proof.KeyID != trusted.KeyID {
		return HubAOCurrentnessAttestation{}, refuse
	}
	for _, id := range consumedCheckIDs {
		if id == attestation.CheckID {
			return HubAOCurrentnessAttestation{}, refuse
		}
	}
	checked, _ := hubAOInstant(attestation.CheckedAt)
	useBy, _ := hubAOInstant(attestation.UseBy)
	if now.Before(checked) || !now.Before(useBy) {
		return HubAOCurrentnessAttestation{}, refuse
	}
	signingBytes, err := HubAOCurrentnessSigningBytes(attestation)
	if err != nil {
		return HubAOCurrentnessAttestation{}, refuse
	}
	signature, err := base64.RawURLEncoding.DecodeString(attestation.Proof.Bytes)
	if err != nil || !ed25519.Verify(trusted.PublicKey, []byte(signingBytes), signature) {
		return HubAOCurrentnessAttestation{}, refuse
	}
	return attestation, nil
}
